package com.fmrent.cars.controller;
import com.fmrent.cars.dto.CarResponse; import com.fmrent.cars.service.CarService; import java.math.BigDecimal; import java.util.List; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
@RestController public class CarController {private final CarService service;public CarController(CarService service){this.service=service;}@GetMapping("/api/cars")public List<CarResponse> list(){return service.list();}@GetMapping("/api/cars/{id}")public CarResponse get(@PathVariable Long id){return service.get(id);}@PostMapping(value="/api/admin/cars",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)@ResponseStatus(HttpStatus.CREATED)public CarResponse create(@RequestParam String name,@RequestParam String category,@RequestParam BigDecimal price,@RequestParam int seats,@RequestParam String transmission,@RequestParam String fuel,@RequestParam(required=false)String badge,@RequestPart("images") List<MultipartFile> images){return service.create(name,category,price,seats,transmission,fuel,badge,images);}@DeleteMapping("/api/admin/cars/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id){service.delete(id);}}
